import{_ as A,C as a,o as e,c as s,a2 as l,b as r,w as E,a as C,E as o,a3 as n}from"./chunks/framework.BBdhqAg0.js";const i="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",x=JSON.parse('{"title":"프로젝트 권한 & 도메인별 보안 정책 (Security Policy)","description":"","frontmatter":{},"headers":[],"relativePath":"work-setting/security-policy.md","filePath":"work-setting/security-policy.md","lastUpdated":1793180713000}'),d={name:"work-setting/security-policy.md"};function g(c,t,D,y,f,u){const B=a("Mermaid");return e(),s("div",null,[t[1]||(t[1]=l('<h1 id="프로젝트-권한-도메인별-보안-정책-security-policy" tabindex="-1">프로젝트 권한 &amp; 도메인별 보안 정책 (Security Policy) <a class="header-anchor" href="#프로젝트-권한-도메인별-보안-정책-security-policy" aria-label="Permalink to &quot;프로젝트 권한 &amp; 도메인별 보안 정책 (Security Policy)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 정책 아키텍처 안내</p><p><img src="'+i+'" alt="보안 정책 다이어그램"><em>관리자 참고: 해당 화면 또는 인포그래픽 이미지를 <code>./images/security-policy.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p>본 문서는 <strong>IBS 건설 관리 시스템</strong>의 워크스페이스 협업 도메인, 본사 경영 도메인, 그리고 부동산 개발 프로젝트 도메인에 적용된 <strong>역할 기반 접근 제어(RBAC) 및 행 단위 데이터 보안(Row-Level Security)</strong> 원칙과 실무 운영 가이드를 안내합니다.</p></blockquote><h2 id="💡-3분-요약-ibs-보안-및-공개-기본-원칙" tabindex="-1">💡 3분 요약: IBS 보안 및 공개 기본 원칙 <a class="header-anchor" href="#💡-3분-요약-ibs-보안-및-공개-기본-원칙" aria-label="Permalink to &quot;💡 3분 요약: IBS 보안 및 공개 기본 원칙&quot;">​</a></h2><p>처음 시스템을 접하는 임직원과 관리자를 위한 핵심 보안 요약입니다:</p><ol><li><strong>공개 워크스페이스는 전사 지식 자산입니다 (열람 개방)</strong>: <ul><li>&#39;공개&#39;로 설정된 워크스페이스의 일반 공지, 업무, 회의록은 <strong>해당 팀 멤버가 아니더라도 전사 임직원이 자유롭게 열람</strong>할 수 있습니다. 지식 사일로를 방지하고 부서 간 협업을 촉진하기 위함입니다.</li><li>단, 글이나 업무를 새로 작성하거나 수정·삭제하는 것은 <strong>반드시 해당 워크스페이스에 참여 중인 멤버만</strong> 가능합니다.</li></ul></li><li><strong>비공개 항목은 철저히 보호됩니다 (완전 차단)</strong>: <ul><li>워크스페이스가 공개 상태이더라도 **&#39;비공개&#39;**로 등록된 업무나 회의록은 <strong>작성자 본인과 지정된 담당자 외에는 누구도 볼 수 없습니다</strong>.</li></ul></li><li><strong>본사 관리와 프로젝트 재무/계약은 엄격히 분리됩니다 (보안 격리)</strong>: <ul><li>인사 평가, 임원 급여, 법인 자금 및 프로젝트 분양 계약/수납 데이터는 워크스페이스의 공개 여부와 상관없이 <strong>해당 권한(역할)을 부여받은 전담 인원에게만 접근이 허용</strong>됩니다.</li></ul></li></ol><h2 id="_1-전사-보안-접근-제어-흐름도" tabindex="-1">1. 전사 보안 접근 제어 흐름도 <a class="header-anchor" href="#_1-전사-보안-접근-제어-흐름도" aria-label="Permalink to &quot;1. 전사 보안 접근 제어 흐름도&quot;">​</a></h2><p>사용자가 화면에서 데이터를 조회하거나 API를 호출할 때 시스템이 검증하는 논리적 절차는 다음과 같습니다.</p>',8)),(e(),r(n,null,{default:E(()=>[o(B,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%EC%82%AC%EC%9A%A9%EC%9E%90%20%ED%99%94%EB%A9%B4%20%EC%A0%91%EC%86%8D%20%2F%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%9A%94%EC%B2%AD%22%5D%20--%3E%20B%7B%22%EC%B5%9C%EA%B3%A0%20%EA%B4%80%EB%A6%AC%EC%9E%90%20%2F%20%EC%B4%9D%EA%B4%84%20%EA%B4%80%EB%A6%AC%EC%9E%90%20%EC%97%AC%EB%B6%80%22%7D%0A%20%20%20%20B%20--%20%22%20%EC%B5%9C%EA%B3%A0%20%EA%B4%80%EB%A6%AC%EC%9E%90%20(%EC%8A%88%ED%8D%BC%EC%9C%A0%EC%A0%80)%20%22%20--%3E%20C%5B%22%EC%A0%84%EC%B2%B4%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EB%B0%8F%20%EB%B3%B4%EC%95%88%20%EA%B2%A9%EB%A6%AC%20%EC%A7%81%EB%AC%B4%20%EC%A0%84%EC%9B%90%20%EC%8A%B9%EC%9D%B8%22%5D%0A%20%20%20%20B%20--%20%22%20%EC%B4%9D%EA%B4%84%20%EC%97%85%EB%AC%B4%EA%B4%80%EB%A6%AC%EC%9E%90%20%22%20--%3E%20C1%7B%22%EB%B3%B4%EC%95%88%20%EA%B2%A9%EB%A6%AC%20%EC%A7%81%EB%AC%B4(%EC%9D%B8%EC%82%AC%ED%8F%89%EA%B0%80%C2%B7%EB%8C%80%EC%99%B8%EB%B9%84%EC%9E%90%EA%B8%88)%EC%9D%B8%EA%B0%80%3F%22%7D%0A%20%20%20%20C1%20--%20Yes%20--%3E%20C2%5B%22%EC%A0%91%EA%B7%BC%20%EC%B0%A8%EB%8B%A8%20(%EC%B5%9C%EA%B3%A0%20%EC%8A%88%ED%8D%BC%EC%9C%A0%EC%A0%80%20%EC%A0%84%EC%9A%A9)%22%5D%0A%20%20%20%20C1%20--%20No%20--%3E%20C3%5B%22%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%A0%84%EC%B2%B4%20%EC%A0%91%EA%B7%BC%20%EC%8A%B9%EC%9D%B8%22%5D%0A%0A%20%20%20%20B%20--%20%22%20%EC%9D%BC%EB%B0%98%20%EC%9E%84%EC%A7%81%EC%9B%90%20(%EA%B5%AC%EC%84%B1%EC%9B%90)%20%22%20--%3E%20D%7B%223%EB%8C%80%20%EB%8F%84%EB%A9%94%EC%9D%B8%20%EA%B5%AC%EB%B6%84%22%7D%0A%20%20%20%20%0A%20%20%20%20D%20--%20%22%201.%20%EB%B3%B8%EC%82%AC%20%EA%B4%80%EB%A6%AC%20%EC%A7%81%EB%AC%B4%20%22%20--%3E%20E%5B%22%EB%B3%B8%EC%82%AC%20%EC%A0%84%EB%8B%B4%20%EC%A7%81%EB%AC%B4%20%EA%B6%8C%ED%95%9C%20%EA%B2%80%EC%A6%9D%20(Strict%20Role%20Security)%22%5D%0A%20%20%20%20%0A%20%20%20%20D%20--%20%22%202.%20%EB%B6%80%EB%8F%99%EC%82%B0%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EA%B4%80%EB%A6%AC%20%22%20--%3E%20F%7B%22%ED%95%B4%EB%8B%B9%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%EC%9D%98%20%EB%A9%A4%EB%B2%84%EC%9D%B8%EA%B0%80%3F%22%7D%0A%20%20%20%20F%20--%20Yes%20--%3E%20F1%5B%22%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EA%B6%8C%ED%95%9C%EB%B3%84%20%EA%B8%B0%EB%8A%A5%20%EC%8A%B9%EC%9D%B8%22%5D%0A%20%20%20%20F%20--%20No%20--%3E%20F2%5B%22%EC%97%B4%EB%9E%8C%20%EC%B0%A8%EB%8B%A8%20(%EB%AA%A9%EB%A1%9D%EC%97%90%EC%84%9C%20%EC%99%84%EC%A0%84%20%EC%A0%9C%EC%99%B8)%22%5D%0A%20%20%20%20%0A%20%20%20%20D%20--%20%22%203.%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%ED%98%91%EC%97%85%20%22%20--%3E%20G%7B%22%EA%B3%B5%EA%B0%9C%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%EC%9D%B8%EA%B0%80%3F%22%7D%0A%20%20%20%20G%20--%20%22%20%EB%B9%84%EA%B3%B5%EA%B0%9C%20%22%20--%3E%20F%0A%20%20%20%20G%20--%20%22%20%EA%B3%B5%EA%B0%9C%20%22%20--%3E%20H%7B%22%EC%9E%91%EC%97%85%20%EC%A2%85%EB%A5%98%22%7D%0A%20%20%20%20H%20--%20%22%20%EC%93%B0%EA%B8%B0%2F%EC%88%98%EC%A0%95%2F%EC%82%AD%EC%A0%9C%20(CUD)%20%22%20--%3E%20F%0A%20%20%20%20H%20--%20%22%20%EC%9D%BD%EA%B8%B0%2F%EC%97%B4%EB%9E%8C%20(Safe%20Methods)%20%22%20--%3E%20I%7B%22%EB%B9%84%EA%B3%B5%EA%B0%9C%20%ED%95%AD%EB%AA%A9(%EB%B9%84%EA%B3%B5%EA%B0%9C%20%EC%97%85%EB%AC%B4%C2%B7%ED%9A%8C%EC%9D%98)%EC%9D%B8%EA%B0%80%3F%22%7D%0A%20%20%20%20I%20--%20Yes%20--%3E%20I1%5B%22%EC%97%B4%EB%9E%8C%20%EC%A0%9C%ED%95%9C%20(%EC%9E%91%EC%84%B1%EC%9E%90%2F%EB%8B%B4%EB%8B%B9%EC%9E%90%20%EC%99%B8%20%EC%B0%A8%EB%8B%A8)%22%5D%0A%20%20%20%20I%20--%20No%20--%3E%20I2%5B%22%EC%A0%84%EC%82%AC%20%EC%9D%BD%EA%B8%B0%20%EC%8A%B9%EC%9D%B8%20(%EC%A0%84%EC%82%AC%20%EC%A7%80%EC%8B%9D%20%EA%B3%B5%EC%9C%A0)%22%5D%0A"})]),fallback:E(()=>[...t[0]||(t[0]=[C(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="_2-3대-도메인별-공개-및-접근-권한-상세-정책" tabindex="-1">2. 3대 도메인별 공개 및 접근 권한 상세 정책 <a class="header-anchor" href="#_2-3대-도메인별-공개-및-접근-권한-상세-정책" aria-label="Permalink to &quot;2. 3대 도메인별 공개 및 접근 권한 상세 정책&quot;">​</a></h2><h3 id="🌐-2-1-워크스페이스-협업-—-전사-읽기-개방-비공개-보호" tabindex="-1">🌐 2.1 워크스페이스 협업 — 전사 읽기 개방 + 비공개 보호 <a class="header-anchor" href="#🌐-2-1-워크스페이스-협업-—-전사-읽기-개방-비공개-보호" aria-label="Permalink to &quot;🌐 2.1 워크스페이스 협업 — 전사 읽기 개방 + 비공개 보호&quot;">​</a></h3><p>전사 소통과 업무 노하우 자산화를 위해 <strong>공개 워크스페이스의 일반 리소스에 대해서는 비멤버 직원에게도 기본 읽기(Read-Only) 권한을 전사적으로 개방</strong>합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">모듈 / 리소스</th><th style="text-align:left;">공개 워크스페이스 정책</th><th style="text-align:left;">비공개 워크스페이스 정책</th><th style="text-align:left;">비공개 보호 장치</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>공지사항</strong></td><td style="text-align:left;">전 임직원 읽기 허용 / 등록·수정은 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>업무 (이슈)</strong></td><td style="text-align:left;">전 임직원 읽기 허용 / 등록·수정은 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 업무/댓글은 작성자 및 담당자 외 <strong>100% 차단</strong></td></tr><tr><td style="text-align:left;"><strong>회의록</strong></td><td style="text-align:left;">전 임직원 읽기 허용 / 등록·수정은 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 회의록은 <strong>100% 차단</strong></td></tr><tr><td style="text-align:left;"><strong>게시판</strong></td><td style="text-align:left;">전 임직원 읽기 허용 / 등록·수정은 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비밀글 및 비공개 카테고리 차단</td></tr><tr><td style="text-align:left;"><strong>캘린더</strong></td><td style="text-align:left;">전 임직원 일정 조회 허용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 업무 및 비공개 회의 일정 자동 제외</td></tr><tr><td style="text-align:left;"><strong>업무실행내역</strong></td><td style="text-align:left;">전 임직원 활동 이력 조회 허용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 업무/댓글 연관 이력 자동 마스킹 및 제외</td></tr></tbody></table><h3 id="🏛️-2-2-본사-관리-—-본사-직무-권한-보안-격리" tabindex="-1">🏛️ 2.2 본사 관리 — 본사 직무 권한 &amp; 보안 격리 <a class="header-anchor" href="#🏛️-2-2-본사-관리-—-본사-직무-권한-보안-격리" aria-label="Permalink to &quot;🏛️ 2.2 본사 관리 — 본사 직무 권한 &amp; 보안 격리&quot;">​</a></h3><p>본사 인사, 조직, 회계, 자금, 감사 직무는 워크스페이스 공개 여부와 무관하게 <strong>해당 직무 역할(Role)이 사전에 부여된 인원에게만 접근을 허용</strong>합니다.</p><ul><li><strong>보안 격리 역할</strong>: <ul><li>인사 평가, 임원 급여, 대외비 자금 계좌 등 고도의 보안이 요구되는 직무는 보안 격리 속성이 적용되어, 일반 업무관리자에게도 노출되지 않으며 <strong>최고 슈퍼유저만 열람 및 통제</strong>할 수 있습니다.</li></ul></li></ul><h3 id="🏗️-2-3-프로젝트-관리-—-엄격한-멤버십-통제-strict-member" tabindex="-1">🏗️ 2.3 프로젝트 관리 — 엄격한 멤버십 통제 (Strict Member) <a class="header-anchor" href="#🏗️-2-3-프로젝트-관리-—-엄격한-멤버십-통제-strict-member" aria-label="Permalink to &quot;🏗️ 2.3 프로젝트 관리 — 엄격한 멤버십 통제 (Strict Member)&quot;">​</a></h3><p>부동산 개발 프로젝트가 공개 상태라 할지라도 <strong>재무, 계약, 수납, 분양 유니트 및 부지 데이터는 오직 해당 프로젝트에 정식 등록된 멤버에게만 접근을 허용</strong>합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">도메인 / 메뉴</th><th style="text-align:left;">관련 모듈 및 업무 내용</th><th style="text-align:left;">공개 프로젝트 접근 정책</th><th style="text-align:left;">비공개 프로젝트 접근 정책</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>프로젝트 설정</code></strong></td><td style="text-align:left;">프로젝트 기본정보, 예산(수입/지출), 동호수 유니트, 타입, 부지(토지 매입 관리)</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>계약 정보 관리</code></strong></td><td style="text-align:left;">차수, 분양 계약, 계약자 정보, 권리의무 양도양수, 해약 관리</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>대금 수납 관리</code></strong></td><td style="text-align:left;">차수별 분양가, 납부회차, 수납 처리, 연체이율 설정</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>회계 자금 관리</code></strong></td><td style="text-align:left;">사업비 전용 통장, 계정과목, 자금 집행 캐시플로우 및 출금 거래</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>문서 소송 관리</code></strong></td><td style="text-align:left;">소송 사건 관리, 법원 판결문 및 4단계 보안등급 문서</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">💡 문서 모듈의 4단계 보안 등급 연동 체계</p><p>문서 모듈은 4단계 보안 등급 체계(1등급 비공개, 2등급 팀공개, 3등급 프로젝트공개, 4등급 전사공개)를 엄격히 준수합니다. 소송 기록물 및 1~2등급 문서는 프로젝트 멤버십 외에도 소속 부서 가드를 추가로 적용하여 이중으로 격리 보호됩니다.</p></div><h2 id="_3-시스템-보안-구현-메커니즘-참고-가이드" tabindex="-1">3. 시스템 보안 구현 메커니즘 (참고 가이드) <a class="header-anchor" href="#_3-시스템-보안-구현-메커니즘-참고-가이드" aria-label="Permalink to &quot;3. 시스템 보안 구현 메커니즘 (참고 가이드)&quot;">​</a></h2><h3 id="_3-1-백엔드-데이터베이스-행-단위-보안-row-level-security" tabindex="-1">3.1 백엔드 데이터베이스 행 단위 보안 (Row-Level Security) <a class="header-anchor" href="#_3-1-백엔드-데이터베이스-행-단위-보안-row-level-security" aria-label="Permalink to &quot;3.1 백엔드 데이터베이스 행 단위 보안 (Row-Level Security)&quot;">​</a></h3><ul><li><strong>목록 조회 시 원천 필터링</strong>: <ul><li>사용자가 속하지 않은 프로젝트의 재무/계약 데이터는 API 요청 시 데이터베이스 쿼리 레벨에서 사전에 걸러지므로, 비인가 사용자의 URL 파라미터 변조(IDOR 공격)를 원천 차단합니다.</li><li>공개 워크스페이스의 업무 목록을 조회할 때도, 다른 사람이 작성한 &#39;비공개&#39; 업무는 쿼리 단계에서 완전히 제외되어 데이터 유출을 원천 방어합니다.</li></ul></li><li><strong>권한 검증 엔진</strong>: <ul><li>기능 실행 시(등록, 수정, 삭제) 사용자의 역할(Role)에 해당 기능 권한 코드가 부여되어 있는지 실시간으로 대조 검증합니다.</li></ul></li></ul><h3 id="_3-2-프론트엔드-사용자-경험-ux-최적화" tabindex="-1">3.2 프론트엔드 사용자 경험 (UX) 최적화 <a class="header-anchor" href="#_3-2-프론트엔드-사용자-경험-ux-최적화" aria-label="Permalink to &quot;3.2 프론트엔드 사용자 경험 (UX) 최적화&quot;">​</a></h3><ul><li><strong>매끄러운 전사 읽기(Read-Only) 지원</strong>: <ul><li>사용자가 자신이 멤버가 아닌 공개 워크스페이스를 둘러볼 때, 불필요한 &#39;권한 없음&#39; 경고 팝업 없이 읽기 전용 화면으로 쾌적하게 내용을 열람할 수 있도록 지원합니다.</li></ul></li><li><strong>권한에 따른 동적 버튼 제어</strong>: <ul><li>수정이나 삭제, 신규 등록 등 권한이 없는 작업 버튼은 화면에서 자동으로 숨겨지거나 비활성화되어 사용자의 혼란을 방지합니다.</li></ul></li></ul>',16))])}const p=A(d,[["render",g]]);export{x as __pageData,p as default};
